   *
   * @param record Avro record to convert
   * @return A new {@link GenericRecord} with all logical type fields converted, or {@code null} if the input is
   *     {@code null}.
   */
  public static GenericRecord convertLogicalType(GenericRecord record) {
    if (record == null) {
      return null;
    }
    Schema schema = record.getSchema();
    GenericRecord result = new GenericData.Record(schema);
    for (Schema.Field field : schema.getFields()) {
      result.put(field.name(), convertValue(field.schema(), record.get(field.name())));
