  /**
   * Converts a single value according to its Avro schema. Unions are resolved to their effective sub-schema before
   * dispatching on the type. Records are converted recursively, arrays and maps have their elements/values converted,
   * and everything else is passed through the logical type conversion.
   */
  private static Object convertValue(Schema schema, Object value) {
    if (value == null) {
      return null;
    }
    Schema effectiveSchema = resolveSchema(schema);
    switch (effectiveSchema.getType()) {
      case RECORD:
        return value instanceof GenericRecord ? convertLogicalType((GenericRecord) value) : value;
      case ARRAY:
        return convertArray(effectiveSchema, value);
      case MAP:
        return convertMap(effectiveSchema, value);
      default:
        return applyLogicalType(effectiveSchema, value);
    }
  }

  private static Object convertArray(Schema arraySchema, Object value) {
    if (!(value instanceof List)) {
      return value;
    }
    Schema elementSchema = arraySchema.getElementType();
    boolean recordElement = resolveSchema(elementSchema).getType() == Schema.Type.RECORD;
    List<?> list = (List<?>) value;
    List<Object> converted = new ArrayList<>(list.size());
    for (Object element : list) {
      if (recordElement && element instanceof GenericRecord) {
        converted.add(convertLogicalType((GenericRecord) element));
      } else {
        converted.add(applyLogicalType(elementSchema, element));
      }
    }
    return converted;
  }

  private static Object convertMap(Schema mapSchema, Object value) {
    if (!(value instanceof Map)) {
      return value;
    }
    Schema valueSchema = mapSchema.getValueType();
    boolean recordValue = resolveSchema(valueSchema).getType() == Schema.Type.RECORD;
    Map<Object, Object> converted = new LinkedHashMap<>();
    for (Map.Entry<?, ?> entry : ((Map<?, ?>) value).entrySet()) {
      Object entryValue = entry.getValue();
      if (recordValue && entryValue instanceof GenericRecord) {
        converted.put(entry.getKey(), convertLogicalType((GenericRecord) entryValue));
      } else {
        converted.put(entry.getKey(), applyLogicalType(valueSchema, entryValue));
      }
    }
    return converted;
  }

  /**
   * Resolves a schema to the sub-schema that should be used for type dispatch. For union schemas, the sub-schema
   * carrying a logical type is preferred; otherwise the first non-null sub-schema is returned.
   */
  private static Schema resolveSchema(Schema schema) {
    if (schema == null || !schema.isUnion()) {
      return schema;
    }
    Schema fallback = null;
    for (Schema curSchema : schema.getTypes()) {
      if (curSchema.getLogicalType() != null) {
        return curSchema;
      }
      if (fallback == null && curSchema.getType() != Schema.Type.NULL) {
        fallback = curSchema;
      }
    }
    return fallback != null ? fallback : schema;
  }
